                 binding["providerDescriptorFields"]),
                ("runtime", "expectedRuntimeDescriptorSha256", "runtimeDescriptorSha256",
                 binding["runtimeDescriptorFields"])):
            descriptor = _admit_descriptor(which, expected[which + "Descriptor"], major)
